addQ("sen-k4-u11", 4, "Teknik Glasir pada Keramik Bakar", "sulit", "Melapisi permukaan gerabah mentah dengan serbuk silika kaca lalu dibakar kembali hingga permukaannya licin berkilau kedap air dinamakan proses ...", ["Pengglasiran (glazing)", "Pengecatan krayon", "Pengamplasan kayu", "Penyepuhan perak"], 0, "Glasir meleleh menjadi lapisan kaca pelindung yang higienis, kedap air, dan berkilau indah.");
addQ("sen-k4-u12", 4, "Fungsi Musik Tradisional Sebagai Sarana Upacara Adat", "sulit", "Di berbagai daerah nusantara, musik tradisional (seperti Gamelan Sekaten di Surakarta atau Gondang Sabangunan di Batak) difungsikan bukan hanya untuk hiburan melainkan sebagai sarana ...", ["Komunikasi ritual adat suci, penyambutan tamu terhormat, dan upacara keagamaan", "Pesta mabuk-mabukan", "Membuat keributan malam hari", "Mengganggu warga yang tidur"], 0, "Musik tradisional mengemban fungsi sakral menghubungkan manusia dengan leluhur dan Sang Pencipta.");
