addQ("sen-k4-u14", 4, "Lagu Daerah Bolelebo dari Nusa Tenggara Timur", "sulit", "Lagu daerah 'Bolelebo ita nusa lelebo...' dari Rote NTT menggambarkan tentang kerinduan mendalam seorang perantau terhadap ...", ["Tanah air kampung halaman yang jauh lebih manis dan dirindukan daripada negeri orang", "Kekayaan uang di kota besar", "Keindahan gedung pencakar langit", "Makanan cepat saji"], 0, "Bolelebo mengungkapkan rasa cinta tanah kelahiran: 'Biar tanah orang panas tapi lebih manis tanah sendiri'.");
addQ("sen-k4-u15", 4, "Analisis Lagu Ayam Den Lapeh dari Ranah Minang", "sulit", "Lagu daerah Minang 'Luruihlah jalan Payakumbuah, babelok jalan ka Kayu Tanam... Ayam den lapeh...' memuat kiasan metafora tentang ...", ["Kehilangan sesuatu yang sangat berharga dalam hidup dan belajar merelakannya dengan sabar", "Ayam peliharaan yang dicuri tetangga", "Resep masakan gulai ayam", "Pertandingan adu ayam jago"], 0, "Metafora 'ayam den lapeh' melambangkan hilangnya harapan atau kekasih berharga yang harus diikhlaskan.");
addQ("sen-k4-u16", 4, "Pola Irama Sinkopasi Musik Tradisional", "sulit", "Aksen ketukan nada yang jatuh tidak pada ketukan kuat birama melainkan bergeser ke ketukan lemah sehingga menghasilkan irama musik yang dinamis dan rancak disebut irama ...", ["Sinkopasi (syncopation)", "Monoton kaku", "Largo lambat", "Hampa nada"], 0, "Sinkopasi memberikan aksen tak terduga yang menghidupkan tempo musik etnik.");
