addQ("sen-k4-u20", 4, "Teknik Cetak Tinggi (Woodcut / Relief Print)", "sulit", "Teknik cetak grafis di mana bagian permukaan papan kayu yang dicungkil akan menjadi bidang kosong putih sedangkan bagian permukaan yang timbul terkena tinta cetak dinamakan cetak ...", ["Tinggi (relief print)", "Dalam (intaglio)", "Datar (litografi)", "Saring (sablon)"], 0, "Cetak tinggi memanfaatkan bagian permukaan yang menonjol untuk memindahkan tinta cetak.");
addQ("sen-k4-u21", 4, "Teknik Cetak Dalam (Intaglio Print)", "sulit", "Teknik cetak di mana tinta justru ditampung di dalam goresan celah-celah garis cekung pelat logam tembaga sebelum dipres ke kertas dinamakan cetak ...", ["Dalam (intaglio)", "Tinggi", "Cap stempel", "Sablon kaos"], 0, "Cetak dalam (etsa/intaglio) menyerap tinta dari goresan alur pelat logam.");
addQ("sen-k4-u22", 4, "Pewarna Alami dari Tanaman Kunyit", "sulit", "Parutan rimpang kunyit menghasilkan cairan pigmen pewarna alami ramah lingkungan berwarna ...", ["Kuning keemasan", "Biru pekat", "Hijau lumut", "Hitam"], 0, "Kurkumin pada rimpang kunyit menghasilkan pewarna alami kuning cerah.");
addQ("sen-k4-u23", 4, "Pewarna Alami Daun Suji", "sulit", "Perasan daun suji atau daun pandan wangi banyak digunakan sebagai pewarna hijau alami yang aman untuk makanan dan kain karena mengandung pigmen ...", ["Klorofil alami", "Karotenoid", "Melanin", "Antosianin"], 0, "Daun suji kaya zat hijau klorofil pekat alami.");
addQ("sen-k4-u24", 4, "Pewarna Alami Daun Tarum (Nila / Indigofera)", "sulit", "Daun tanaman tarum (Indigofera tinctoria) difermentasi menghasilkan pasta pewarna alami tradisional untuk kain tenun dan batik berwarna ...", ["Biru nila (indigo)", "Merah darah", "Kuning lemon", "Putih"], 0, "Indigofera menghasilkan warna biru nila alami yang awet menawan.");
addQ("sen-k4-u25", 4, "Pewarna Alami Kulit Pohon Tingi dan Soga", "sulit", "Ekstrak rebusan kulit kayu pohon tingi, tegeran, dan soga jambal menghasilkan pewarna alami batik klasik khas keraton bernuansa warna ...", ["Cokelat soga khas Yogyakarta dan Surakarta", "Merah muda terang", "Hijau neon", "Biru muda"], 0, "Soga menghasilkan warna cokelat keemasan khas batik pedalaman Mataram.");
addQ("sen-k4-u26", 4, "Keunggulan Bahan Pewarna Alami Dibandingkan Kimiawi", "sulit", "Penggunaan zat pewarna alami dari dedaunan dan kulit kayu pohon lebih ramah lingkungan karena ...", ["Limbahnya mudah terurai secara hayati (biodegradable) dan tidak meracuni ekosistem sungai", "Warnanya sangat menyilaukan mata", "Bisa bertahan selama satu abad tanpa dicuci", "Harganya jutaan rupiah"], 0, "Pewarna alami organik tidak mengandung logam berat beracun ramah ekologis.");
addQ("sen-k4-u27", 4, "Pementasan Musik Keroncong Nusantara", "sulit", "Alat musik petik berdawai kecil dengan suara gemerincing khas 'cak' dan 'cuk' merupakan instrumen inti dalam orkes musik khas nusantara yaitu musik ...", ["Keroncong", "Dangdut koplo", "Rock", "Gamelan baleganjur"], 0, "Ukulele cuk dan cak memberi jalinan harmoni ritmis khas musik keroncong Indonesia.");
addQ("sen-k4-u28", 4, "Alat Musik Gesek Rebab Tradisional", "sulit", "Rebab adalah alat musik gesek tradisional dengan dua senar kawat dan tabung resonansi kayu berlapis kulit tipis. Dalam gamelan Jawa, rebab berfungsi sebagai ...", ["Pemberi melodi pembuka gending dan pengarah nada vokal sinden", "Pemukul kendang", "Penghitung ketukan birama", "Hanya hiasan panggung"], 0, "Gesekan rebab yang menyayat hati memandu alur melodi vokal karawitan.");
addQ("sen-k4-u29", 4, "Pementasan Tari Gending Sriwijaya", "sulit", "Tari Gending Sriwijaya dari Sumatera Selatan dipentaskan dengan keagungan kostum Aesan Gede untuk menyambut tamu agung kenegaraan. Penari utama membawa tepak sirih kuningan berisi ...", ["Sekapur sirih yang dipersembahkan kepada tamu kehormatan sebagai tanda selamat datang", "Emas batangan", "Batu permata", "Bunga mawar merah"], 0, "Sekapur sirih adalah lambang keramahan dan penghormatan tulus masyarakat Palembang.");
addQ("sen-k4-u30", 4, "Sikap Menghargai Hak Cipta Karya Seni Orang Lain", "sulit", "Menjiplak atau meniru lukisan karya seniman lain lalu mengakuinya sebagai buatan sendiri tanpa izin dinamakan plagiarisme. Tindakan yang beretika dan menghormati hak cipta adalah ...", ["Mencantumkan nama seniman asli dan meminta izin resmi bila mengadaptasi karyanya", "Menghapus tanda tangan pelukis asli", "Menjual foto lukisan orang lain di internet", "Membakar karya orang lain"], 0, "Menghargai hak kekayaan intelektual (HAKI) mencerminkan integritas moral insan berbudaya.");

