addQ("sen-k5-m01", 5, "Pengertian Seni Batik", "mudah", "Karya seni rupa terapan adiluhung warisan bangsa Indonesia yang dibuat dengan teknik perintangan warna menggunakan malam (lilin) panas adalah ...", ["Batik", "Anyaman", "Mozaik", "Patung"], 0, "Batik adalah warisan kemanusiaan UNESCO dari Indonesia berbasis rintang malam.");
addQ("sen-k5-m02", 5, "Alat Menulis Batik Canting", "mudah", "Alat tembaga kecil bercucuk dengan pegangan kayu yang digunakan untuk menorehkan cairan lilin malam pada kain batik tulis dinamakan ...", ["Canting", "Kuas", "Pahat", "Sudip"], 0, "Canting adalah pena tembaga tradisional penoreh malam panas.");
addQ("sen-k5-m03", 5, "Bahan Perintang Batik Malam (Lilin)", "mudah", "Bahan utama yang dipanaskan di wajan kecil dan berfungsi merintangi masuknya warna pada serat kain batik dinamakan ...", ["Lilin malam (wax)", "Minyak goreng", "Cat tembok", "Lem kanji"], 0, "Lilin malam merintangi serat kain agar tidak terwarnai saat pencelupan.");
addQ("sen-k5-m04", 5, "Motif Batik Mega Mendung", "mudah", "Motif batik khas pesisir Cirebon yang berbentuk gumpalan awan bergaris tegas bertingkat warna gradasi dinamakan motif ...", ["Mega Mendung", "Kawung", "Parang Rusak", "Truntum"], 0, "Mega Mendung adalah motif awan khas karya seniman batik Cirebon.");
addQ("sen-k5-m05", 5, "Tangga Nada Diatonis Mayor Ciri", "mudah", "Tangga nada diatonis mayor memiliki ciri lagu yang bersemangat, ceria, dan biasanya diawali serta diakhiri dengan nada ...", ["Do (1)", "La (6)", "Fa (4)", "Si (7)"], 0, "Tangga nada mayor berpusat pada nada tonika 'do' (C mayor: C = do).");
addQ("sen-k5-m06", 5, "Tangga Nada Diatonis Minor Ciri", "mudah", "Tangga nada diatonis minor memiliki sifat lagu yang haru, sedih, dan khidmat, serta biasanya berpusat diawali nada ...", ["La (6)", "Do (1)", "Mi (3)", "Sol (5)"], 0, "Tangga nada minor alami berpusat pada nada tonika 'la' (A minor: A = la).");
addQ("sen-k5-m07", 5, "Interval Tangga Nada Mayor", "mudah", "Susunan jarak interval tangga nada diatonis mayor yang benar adalah ...", ["1 - 1 - 1/2 - 1 - 1 - 1 - 1/2", "1 - 1/2 - 1 - 1 - 1/2 - 1 - 1", "1 - 1 - 1 - 1/2 - 1 - 1 - 1/2", "1/2 - 1 - 1 - 1 - 1/2 - 1 - 1"], 0, "Interval mayor: 1 - 1 - 1/2 - 1 - 1 - 1 - 1/2.");
addQ("sen-k5-m08", 5, "Akord Dasar Musik Triad", "mudah", "Kumpulan tiga nada atau lebih yang dibunyikan secara bersamaan dan menghasilkan paduan suara yang harmonis dinamakan ...", ["Akord (akor / chord)", "Melodi tunggal", "Tempo ketukan", "Birama"], 0, "Akor adalah paduan tiga nada atau lebih yang berbunyi serempak selaras.");
addQ("sen-k5-m09", 5, "Tari Merak Jawa Barat", "mudah", "Tari kreasi daerah Jawa Barat yang menirukan keanggunan burung merak jantan memamerkan keindahan bulu ekornya yang mekar adalah Tari ...", ["Merak", "Kancet Papatai", "Saman", "Pendet"], 0, "Tari Merak diciptakan seniman Raden Tjetje Somantri melukiskan burung merak.");
addQ("sen-k5-m10", 5, "Tokoh Punokawan Semar", "mudah", "Tokoh punakawan wayang kulit yang paling tua, bijaksana, sabar, bertubuh bulat, dan merupakan penjelmaan dewa Ismaya adalah Ki Lurah ...", ["Semar", "Gareng", "Petruk", "Bagong"], 0, "Kyai Semar adalah pamong agung punakawan simbol kearifan rakyat kecil.");

addQ("sen-k5-s01", 5, "Proses Pembuatan Batik Celup Ikat (Jumputan)", "sedang", "Kain putih diikat kencang menggunakan karet atau tali rafia lalu dicelupkan ke dalam larutan pewarna menghasilkan motif lingkaran warna unik. Teknik ini dinamakan batik ...", ["Jumputan (ikat celup / tie-dye)", "Tulis canting", "Cap tembaga", "Sablon"], 0, "Jumputan mengandalkan ikatan tali kencang merintangi resapan cairan pewarna.");
addQ("sen-k5-s02", 5, "Teknik Batik Cap Menggunakan Cap Tembaga", "sedang", "Batik yang diproduksi secara cepat dalam jumlah banyak menggunakan lempengan cap tembaga bermotif yang dicelupkan ke malam panas dinamakan batik ...", ["Cap", "Tulis tangan", "Lukis kanvas", "Bordir"], 0, "Batik cap mempercepat proses pembuatan motif batik secara repetitif seragam.");
addQ("sen-k5-s03", 5, "Tahap Ngelorod pada Pembuatan Batik", "sedang", "Proses merebus kain batik yang telah selesai diwarnai ke dalam air mendidih untuk melunturkan dan melepaskan seluruh lapisan lilin malam dinamakan tahap ...", ["Ngelorod (melarutkan malam)", "Mencanting", "Menyungging", "Mewarnai"], 0, "Ngelorod adalah tahap perebusan air mendidih untuk melepaskan malam dari serat kain.");
addQ("sen-k5-s04", 5, "Motif Batik Truntum Keraton", "sedang", "Motif batik berbentuk bunga melati bintang-bintang kecil yang diciptakan Kanjeng Ratu Kencana bermakna cinta yang bersemi kembali adalah motif ...", ["Truntum", "Parang", "Mega mendung", "Sekar jagad"], 0, "Truntum (dari kata tumeruntum) melambangkan cinta tulus yang tumbuh mekar bersemi.");
addQ("sen-k5-s05", 5, "Motif Batik Sekar Jagad", "sedang", "Motif batik klasik 'Sekar Jagad' yang memadukan bermacam-macam motif pulau keindahan bunga dunia melambangkan ...", ["Keindahan dan keanekaragaman dunia yang harmonis", "Peperangan antarbangsa", "Kekeringan tanah", "Kematian"], 0, "Sekar Jagad (bunga dunia) menggambarkan peta keindahan keragaman nusantara.");
addQ("sen-k5-s06", 5, "Interval Tangga Nada Diatonis Minor Alami", "sedang", "Susunan jarak interval nada pada tangga nada diatonis minor asli (alami) adalah ...", ["1 - 1/2 - 1 - 1 - 1/2 - 1 - 1", "1 - 1 - 1/2 - 1 - 1 - 1 - 1/2", "1 - 1 - 1 - 1/2 - 1 - 1 - 1/2", "1/2 - 1 - 1 - 1 - 1 - 1/2 - 1"], 0, "Interval minor alami: 1 - 1/2 - 1 - 1 - 1/2 - 1 - 1.");
addQ("sen-k5-s07", 5, "Akor Mayor C (C-E-G)", "sedang", "Susunan nada pembentuk akord C Mayor dasar pada tuts piano atau alat musik melodis adalah nada ...", ["C - E - G (do - mi - sol)", "C - D - E", "C - F - A", "C - G - B"], 0, "Akor C Mayor tersusun dari nada tonika C, terts besar E, dan kuint murni G.");
addQ("sen-k5-s08", 5, "Akor Minor A (A-C-E)", "sedang", "Susunan nada pembentuk akord A minor (Am) dasar adalah paduan nada ...", ["A - C - E (la - do - mi)", "A - B - C", "A - D - F", "A - E - G"], 0, "Akor Am tersusun dari nada A, terts kecil C, dan kuint E.");
addQ("sen-k5-s09", 5, "Alat Musik Harmonis Gitar Enam Senar", "sedang", "Alat musik petik yang memiliki enam dawai senar dan mampu memainkan akor melodi dan harmoni pengiring lagu sekaligus adalah ...", ["Gitar akustik", "Tamborin", "Triangle", "Kendang"], 0, "Gitar adalah instrumen kordofon harmonis serbaguna.");
addQ("sen-k5-s10", 5, "Pencipta Tari Merak Jawa Barat", "sedang", "Koreografer seniman tari Sunda ternama yang menciptakan Tari Merak pertama kali pada tahun 1950-an adalah ...", ["Raden Tjetje Somantri", "Bagong Kussudiardja", "Guruh Soekarnoputra", "Didik Nini Thowok"], 0, "Raden Tjetje Somantri mengkreasikan Tari Merak Sunda yang megah.");
addQ("sen-k5-s11", 5, "Tari Gambyong dari Jawa Tengah", "sedang", "Tarian tradisional dari Surakarta yang dibawakan dengan gerakan lemah gemulai untuk menyambut tamu kehormatan atau upacara panen padi adalah Tari ...", ["Gambyong", "Jaipong", "Kecak", "Saman"], 0, "Tari Gambyong adalah tarian klasik Keraton Mangkunegaran penyambut tamu.");
addQ("sen-k5-s12", 5, "Tari Gandrung dari Banyuwangi", "sedang", "Tarian tradisional kebanggaan masyarakat Blambangan Banyuwangi (Jawa Timur) yang dibawakan penari wanita berkipas diiringi kendang kempul adalah Tari ...", ["Gandrung", "Remo", "Topeng Malangan", "Reog"], 0, "Banyuwangi dijuluki Kota Gandrung berkat tarian agung ini.");
addQ("sen-k5-s13", 5, "Tari Remo dari Jawa Timur", "sedang", "Tarian tradisional khas Jawa Timur yang menampilkan gerakan kaki yang lincah menghentakkan gelang lonceng gemerincing (gongseng) untuk menyambut pembukaan pementasan Ludruk adalah Tari ...", ["Remo", "Gambyong", "Pendet", "Gandrung"], 0, "Tari Remo menggambarkan kegagahan seorang ksatria dengan gongseng di pergelangan kaki.");
addQ("sen-k5-s14", 5, "Karakter Tokoh Protagonis Teater", "sedang", "Dalam pementasan sandiwara drama teater, tokoh utama yang berwatak baik hati, jujur, setia, dan membela kebenaran dinamakan tokoh ...", ["Protagonis", "Antagonis", "Tritagonis", "Figuran"], 0, "Protagonis adalah karakter sentral pembawa nilai-nilai kebaikan.");
addQ("sen-k5-s15", 5, "Karakter Tokoh Antagonis Teater", "sedang", "Tokoh dalam cerita sandiwara teater yang berwatak jahat, curang, iri dengki, dan menjadi penentang tokoh utama dinamakan tokoh ...", ["Antagonis", "Protagonis", "Tritagonis", "Sutradara"], 0, "Antagonis adalah tokoh pemicu konflik penentang tokoh protagonis.");
addQ("sen-k5-s16", 5, "Karakter Tokoh Tritagonis Teater", "sedang", "Tokoh penengah yang bijaksana, adil, dan membantu mendamaikan pertentangan antara tokoh protagonis dan antagonis dinamakan tokoh ...", ["Tritagonis", "Pemeran pembantu", "Figuran", "Penata panggung"], 0, "Tritagonis adalah juru damai penengah jalannya cerita.");
addQ("sen-k5-s17", 5, "Tokoh Punokawan Petruk yang Cerdik", "sedang", "Anak kedua Semar yang berbadan jangkung tinggi dengan hidung panjang mancung dan jenaka cerdas adalah ...", ["Petruk (Kanthong Bolong)", "Gareng", "Bagong", "Togog"], 0, "Petruk berhidung mancung panjang, jenaka, dan pandai bersilat lidah.");
addQ("sen-k5-s18", 5, "Tokoh Punokawan Gareng", "sedang", "Anak sulung Semar yang berkaki pincang, bertangan cekot (bengkok), dan bermata juling yang melambangkan kehati-hatian melangkah dalam hidup adalah ...", ["Gareng (Nala Gareng)", "Petruk", "Bagong", "Bilung"], 0, "Cacat fisik Gareng mengandung filosofi mawas diri dan kehati-hatian bertindak.");
addQ("sen-k5-s19", 5, "Tokoh Punokawan Bagong yang Kritis", "sedang", "Anak bungsu Semar yang berbadan bulat tambun, bermata lebar, dan berani mengkritik para ksatria yang keliru secara blak-blakan adalah ...", ["Bagong (Bawor)", "Petruk", "Gareng", "Semar"], 0, "Bagong adalah representasi suara kritis rakyat jelata yang jujur.");
addQ("sen-k5-s20", 5, "Pencipta Lagu Nasional Hari Merdeka", "sedang", "Lagu perjuangan nasional 'Tujuh belas Agustus tahun empat lima, itulah hari kemerdekaan kita...' diciptakan oleh komponis ...", ["Husein Mutahar (H. Mutahar)", "W.R. Soepratman", "Ismail Marzuki", "Cornel Simanjuntak"], 0, "H. Mutahar menciptakan lagu mars Hari Merdeka dan Syukur.");

addQ("sen-k5-u01", 5, "Analisis Filosofi Motif Parang Barong Keraton", "sulit", "Motif batik 'Parang Barong' berukuran besar diciptakan oleh Sultan Agung Hanyokrokusumo dari Mataram. Nilai filosofis mendalam dari motif Parang Barong adalah ...", ["Tanggung jawab luhur seorang raja pemimpin yang selalu mawas diri dan berjuang membela kebenaran tanpa henti", "Pamer kekayaan harta istana", "Keinginan menguasai lautan dunia", "Simbol kesedihan duka cita"], 0, "Parang Barong adalah batik larangan para raja Mataram simbol kepemimpinan adiluhung.");
addQ("sen-k5-u02", 5, "Filosofi Motif Batik Kawung Empat Penjuru", "sulit", "Empat bulatan lonjong pada motif batik Kawung yang mengelilingi satu titik pusat melambangkan filosofi kearifan Jawa yaitu ...", ["Sedulur Papat Limo Pancer (empat unsur alam yang menyatu pada satu titik kesadaran batin)", "Empat jenis mata uang kuno", "Empat musim di dunia barat", "Empat jenis hewan buas"], 0, "Kawung melambangkan harmoni 4 anasir alam (air, angin, api, tanah) di bawah kendali pancer jiwa.");
addQ("sen-k5-u03", 5, "Teknik Membatik Canting Tulis Alusan", "sulit", "Pada batik tulis alusan keraton, proses penorehan malam panas dilakukan di kedua sisi kain (depan dan belakang) secara tembus presisi yang dinamakan proses ...", ["Ngengreng (depan) dan Nerusi (membatik sisi belakang tembus)", "Ngelorod ganda", "Menyablon", "Mencap"], 0, "Membatik bolak-balik (nerusi) menjamin lilin malam menembus sempurna ke kedua sisi kain.");
addQ("sen-k5-u04", 5, "Analisis Akord Mayor vs Minor Secara Interval", "sulit", "Perbedaan jarak interval pembentuk akord Mayor dan Minor adalah ...", ["Akor Mayor tersusun dari interval terts besar (2 nada) lalu terts kecil (1 1/2 nada), sedangkan Akor Minor sebaliknya terts kecil dulu lalu terts besar", "Akor Mayor hanya memiliki satu nada", "Akor Minor tidak berbunyi", "Keduanya memiliki interval yang sama persis"], 0, "Mayor = 2 + 1,5 nada (terts besar + kuint murni); Minor = 1,5 + 2 nada (terts kecil + kuint murni).");
addQ("sen-k5-u05", 5, "Analisis Akord Tingkat I, IV, dan V (Akord Pokok)", "sulit", "Dalam tangga nada C mayor, tiga akord utama (akord primer / trinada pokok) yang sering digunakan untuk mengiringi lagu adalah ...", ["C mayor (Tonika), F mayor (Subdominan), dan G mayor (Dominan)", "Dm, Em, dan Am", "B diminished saja", "Fm dan Gm"], 0, "Tingkat I (C), IV (F), dan V (G) adalah tiga pilar akor primer tangga nada C mayor.");
addQ("sen-k5-u06", 5, "Fungsi Akor Dominan Ketujuh (G7)", "sulit", "Akor G7 (G - B - D - F) dalam tangga nada C mayor memiliki sifat tensi ketegangan yang menuntut penyelesaian resolusi kembali menuju akord ...", ["C mayor (Tonika)", "D minor", "E minor", "A minor"], 0, "Akor dominan 7th selalu mencari resolusi alami kembali ke akor tonika I (C).");
addQ("sen-k5-u07", 5, "Analisis Struktur Akord Minor Harmonik", "sulit", "Tangga nada minor harmonik dibentuk dengan cara menaikkan nada ke- ... setengah laras saat naik maupun turun.", ["Tujuh (nada ke-7 dinaikkan 1/2 laras)", "Tiga", "Lima", "Empat"], 0, "Minor harmonik menaikkan nada ke-7 (leading tone) untuk menciptakan tarikan kuat ke tonika.");
addQ("sen-k5-u08", 5, "Koreografi Simetris vs Asimetris Tari Kelompok", "sulit", "Susunan formasi penari kelompok yang sisi kanan dan kirinya memiliki susunan gerak atau posisi yang sama persis dinamakan formasi ...", ["Simetris (memberi kesan ketertiban, ketenangan, dan formalitas resmi)", "Asimetris dinamis", "Acak semrawut", "Patahan sudut"], 0, "Formasi simetris memancarkan kestabilan, keteraturan, dan kedamaian formal.");
addQ("sen-k5-u09", 5, "Koreografi Asimetris Tari Dinamis", "sulit", "Formasi penari yang sengaja dibuat berbeda antara sisi panggung kanan dan kiri untuk memberikan efek kejutan dan kedinamisan gerak dinamakan formasi ...", ["Asimetris", "Simetris", "Segitiga kaku", "Garis lurus"], 0, "Formasi asimetris memberikan variasi visual yang hidup dan penuh ketegangan artistik.");
addQ("sen-k5-u10", 5, "Analisis Pementasan Tari Saman dan Peran Syeikh (Pemimpin)", "sulit", "Dalam pertunjukan Tari Saman dari Gayo Lues, penari yang duduk di tengah barisan bertindak sebagai pemimpin nyanyian syair dan penentu perubahan tempo gerak dinamakan ...", ["Syeikh (pengangkat)", "Dalang", "Kiper", "Bupati"], 0, "Syeikh memimpin lantunan vokal syair dakwah dan memandu transisi ritme gerak saman.");
addQ("sen-k5-u11", 5, "Pementasan Teater Tradisional Ketoprak Jawa", "sulit", "Seni teater rakyat tradisional Jawa Tengah yang menceritakan kisah babad sejarah kerajaan Jawa (Majapahit, Mataram) dengan dialog bahasa Jawa diiringi gamelan adalah ...", ["Ketoprak", "Ludruk", "Lenong", "Randai"], 0, "Ketoprak menyajikan sandiwara sejarah keraton berbalut humor dan gamelan.");
addQ("sen-k5-u12", 5, "Pementasan Teater Tradisional Ludruk Jawa Timur", "sulit", "Seni teater rakyat dari Jawa Timur yang mengangkat kisah kehidupan rakyat sehari-hari dengan guyonan khas bahasa Suroboyoan dan diawali tarian Remo adalah ...", ["Ludruk", "Ketoprak", "Makyong", "Arja"], 0, "Ludruk adalah teater rakyat Jawa Timuran yang egaliter dan kental kritik sosial.");
addQ("sen-k5-u13", 5, "Pementasan Teater Tradisional Lenong Betawi", "sulit", "Teater komedi tradisional khas Betawi yang dimainkan dengan dialog spontan jenaka diiringi musik Gambang Kromong dinamakan ...", ["Lenong", "Ketoprak", "Mamanda", "Longser"], 0, "Lenong Betawi (Lenong Denes dan Preman) memadukan humor ceplas-ceplos Betawi.");
addQ("sen-k5-u14", 5, "Pementasan Teater Tradisional Mamanda Kalimantan Selatan", "sulit", "Seni sandiwara teater tradisional dari suku Banjar Kalimantan Selatan yang menceritakan dinamika istana raja dipimpin oleh tokoh wazir dinamakan ...", ["Mamanda", "Lenong", "Ludruk", "Ketoprak"], 0, "Mamanda menampilkan struktur cerita kesultanan Banjar dengan tokoh Wazir dan Perdana Menteri.");
addQ("sen-k5-u15", 5, "Pementasan Teater Tradisional Makyong Riau", "sulit", "Seni pertunjukan teater tari tradisional istana di Kepulauan Riau yang diakui UNESCO dan dimainkan dengan topeng serta rebab adalah ...", ["Makyong", "Randai", "Ubrug", "Komedie Stamboel"], 0, "Makyong adalah warisan seni pertunjukan Melayu kuno yang sakral dan memesona.");
addQ("sen-k5-u16", 5, "Seni Grafis Cetak Saring (Sablon Kaus)", "sulit", "Teknik cetak seni grafis yang menggunakan kain kasa berpori halus (screen mesh) dan rakel karet untuk menyapukan tinta cat pada kain kaos dinamakan ...", ["Cetak saring (sablon / serigrafi)", "Cetak tinggi cukil kayu", "Cetak dalam etsa", "Cetak cap stempel"], 0, "Sablon (serigrafi) menembuskan tinta melalui pori terbuka kain screen.");
addQ("sen-k5-u17", 5, "Alat Rakel Karet pada Sablon", "sulit", "Bilah karet pipih berpegangan kayu atau aluminium yang digunakan untuk meratakan dan menekan tinta menembus kain screen sablon dinamakan ...", ["Rakel sablon", "Canting", "Pahat cungkil", "Kuas bulu"], 0, "Rakel karet menyapu dan menekan pasta tinta secara presisi ke media cetak.");
addQ("sen-k5-u18", 5, "Fungsi Emulsi Foto pada Cetak Sablon", "sulit", "Cairan peka cahaya (seperti diazo / afdruk) yang dioleskan pada kain screen untuk memindahkan gambar desain negatif melalui penyinaran dinamakan ...", ["Emulsi afdruk sablon", "Cat minyak", "Malam lilin", "Tinta prada"], 0, "Emulsi foto membentuk pola rintangan stensil pada kain screen setelah diekspos cahaya.");
addQ("sen-k5-u19", 5, "Pencipta Lagu Nasional Rayuan Pulau Kelapa", "sulit", "Lagu wajib 'Tanah airku aman dan makmur, pulau kelapa yang amat subur...' yang melukiskan keindahan maritim Indonesia diciptakan oleh maestro ...", ["Ismail Marzuki", "W.R. Soepratman", "C. Simanjuntak", "Kusbini"], 0, "Ismail Marzuki melukiskan keelokan zamrud khatulistiwa dalam Rayuan Pulau Kelapa.");
addQ("sen-k5-u20", 5, "Pencipta Lagu Nasional Maju Tak Gentar", "sulit", "Lagu perjuangan berirama mars bersemangat 'Maju tak gentar membela yang benar...' diciptakan oleh komponis pejuang ...", ["Cornel Simanjuntak (C. Simanjuntak)", "H. Mutahar", "Ibu Sud", "A.T. Mahmud"], 0, "Cornel Simanjuntak menggelorakan semangat juang laskar rakyat dalam Maju Tak Gentar.");
addQ("sen-k5-u21", 5, "Pencipta Lagu Nasional Indonesia Pusaka", "sulit", "Lagu yang sangat menyentuh kalbu 'Indonesia tanah air beta, pusaka abadi nan jaya...' diciptakan oleh ...", ["Ismail Marzuki", "W.R. Soepratman", "Sudharnoto", "Kusbini"], 0, "Indonesia Pusaka adalah mahakarya abadi Ismail Marzuki.");
addQ("sen-k5-u22", 5, "Pencipta Lagu Syukur H Mutahar", "sulit", "Lagu wajib penuh renungan syukur 'Dari yakinku teguh, cinta ikhlasku penuh...' diciptakan oleh komponis ...", ["H. Mutahar", "Gesang", "Ibu Sud", "Pak Kasur"], 0, "Lagu khidmat Syukur diciptakan H. Mutahar saat masa revolusi fisik kemerdekaan.");
addQ("sen-k5-u23", 5, "Pencipta Lagu Bengawan Solo Gesang", "sulit", "Lagu keroncong legendaris 'Bengawan Solo' yang terkenal hingga ke Jepang dan seluruh Asia diciptakan oleh maestro keroncong ...", ["Gesang Martohartono", "Ismail Marzuki", "Waldjinah", "Mus Mulyadi"], 0, "Gesang menciptakan Bengawan Solo di tepi Sungai Bengawan Solo pada tahun 1940.");
addQ("sen-k5-u24", 5, "Teknik Patung Memahat Kayu Jati Jepara", "sulit", "Mengurangi bongkahan kayu secara bertahap menggunakan alat pahat besi dan palu kayu (ganden) hingga membentuk figur patung dinamakan teknik ...", ["Memahat (carving)", "Mengecor", "Membusir", "Menganyam"], 0, "Memahat adalah teknik subtraktif mengurangi massa bahan keras (kayu/batu).");
addQ("sen-k5-u25", 5, "Teknik Patung Cor Logam Perunggu", "sulit", "Membuat patung dengan menuangkan cairan logam perunggu atau gips panas ke dalam cetakan rongga cetak dinamakan teknik ...", ["Mengecor (cetak tuang / casting)", "Memahat batu", "Membatik", "Menyulam"], 0, "Mengecor mencairkan bahan logam lalu menuangkannya ke mold cetakan negatif.");
addQ("sen-k5-u26", 5, "Teknik Patung Konstruksi Merakit Logam", "sulit", "Menyambungkan potongan-potongan besi pelat bekas menggunakan mesin las listrik hingga membentuk patung robotik dinamakan teknik ...", ["Konstruksi (assembling / merakit)", "Memahat kayu", "Membusir lilin", "Menenun"], 0, "Teknik konstruksi menyatukan berbagai elemen material menjadi kesatuan bentuk 3D.");
addQ("sen-k5-u27", 5, "Ragam Gerak Tari Zapin Melayu Riau", "sulit", "Tari Zapin khas rumpun Melayu dipentaskan dengan langkah kaki lincah yang sarat gerak lompatan kecil diiringi petikan gambus dan gendang marwas. Nilai budaya Tari Zapin adalah ...", ["Kesantunan adab Melayu yang bernafaskan nilai-nilai religius Islam", "Peperangan bersenjata", "Mistik takhayul", "Pamer kekuatan fisik"], 0, "Zapin mencerminkan kesantunan pergaulan dan syiar dakwah persaudaraan.");
addQ("sen-k5-u28", 5, "Seni Tari Piring Menginjak Pecahan Kaca Piring", "sulit", "Pada atraksi puncak pertunjukan Tari Piring Minangkabau, para penari melakukan atraksi akrobatik menginjak pecahan beling piring tajam tanpa terluka yang melambangkan ...", ["Keteguhan iman, kesucian hati, dan perlindungan dari marabahaya", "Sihir tipuan mata", "Kekebalan senjata api", "Kemarahan kepada penonton"], 0, "Atraksi menari di atas pecahan piring menyimbolkan kebersihan niat dan keteguhan batin.");
addQ("sen-k5-u29", 5, "Harmoni Musik Vokal Paduan Suara (Choir)", "sulit", "Dalam paduan suara empat suara (SATB), pembagian jenis suara wanita tinggi dan suara pria rendah adalah ...", ["Sopran (wanita tinggi) dan Bass (pria rendah)", "Tenor dan Alto", "Alto dan Mezzo", "Bariton dan Sopran"], 0, "SATB: Sopran (wanita tinggi), Alto (wanita rendah), Tenor (pria tinggi), Bass (pria rendah).");
addQ("sen-k5-u30", 5, "Pentingnya Menjaga Kelestarian Warisan Budaya Nusantara", "sulit", "Upaya nyata generasi muda sekolah dasar untuk melestarikan kesenian tradisional nusantara di era modernisasi adalah ...", ["Mempelajari, mencintai, dan bangga menampilkan tarian serta alat musik daerah di berbagai pentas budaya", "Menganggap kesenian tradisional kuno dan memalukan", "Hanya menyukai budaya barat dan K-pop", "Menolak menyanyikan lagu daerah"], 0, "Mempelajari dan mengapresiasi seni tradisi menjaga identitas kebudayaan bangsa tetap lestari.");

