addQ("sen-k6-m01", 6, "Pengertian Reklame Visual", "mudah", "Karya seni grafis yang memuat gambar dan tulisan menarik untuk mempromosikan barang dagangan atau menyampaikan pesan sosial kepada masyarakat luas disebut ...", ["Reklame (iklan)", "Lukisan murni", "Patung relief", "Komik fabel"], 0, "Reklame bertujuan menginformasikan, mengajak, atau mempromosikan produk/jasa kepada khalayak.");
addQ("sen-k6-m02", 6, "Media Reklame Poster", "mudah", "Reklame visual berupa selembar kertas bergambar menarik dan berisi kalimat ajakan yang ditempelkan di dinding tempat umum adalah ...", ["Poster", "Spanduk", "Baliho", "Katalog"], 0, "Poster adalah plakat selebaran visual di tempat publik.");
addQ("sen-k6-m03", 6, "Media Reklame Spanduk", "mudah", "Reklame kain panjang yang dibentangkan melintang di atas jalan raya atau di antara dua tiang dinamakan ...", ["Spanduk", "Poster", "Brosur", "Leaflet"], 0, "Spanduk dibuat dari kain/fleksi panjang terbentang horizontal.");
addQ("sen-k6-m04", 6, "Media Reklame Baliho Raksasa", "mudah", "Reklame visual berukuran sangat besar yang dipasang di tepi jalan protokol perkotaan pada konstruksi tiang besi permanen dinamakan ...", ["Baliho (billboard)", "Brosur", "Stiker", "Kartu nama"], 0, "Baliho berukuran raksasa dipasang permanen di tepi jalan raya.");
addQ("sen-k6-m05", 6, "Media Reklame Brosur", "mudah", "Lembaran kertas cetak lipat yang dibagikan secara cuma-cuma kepada pengunjung pameran untuk menyampaikan informasi detail produk dinamakan ...", ["Brosur (pamflet)", "Baliho", "Spanduk", "Papan nama"], 0, "Brosur dibagikan langsung ke tangan konsumen memuat rincian produk.");
addQ("sen-k6-m06", 6, "Logo Lambang Perusahaan", "mudah", "Gambar lambang atau simbol visual sederhana yang mewakili identitas resmi suatu lembaga, sekolah, atau perusahaan dinamakan ...", ["Logo", "Spanduk", "Poster", "Baliho"], 0, "Logo adalah identitas visual grafis ringkas dan bermakna.");
addQ("sen-k6-m07", 6, "Interval Nada Prim (1 ke 1)", "mudah", "Jarak antara satu nada ke nada yang sama persis (misalnya dari nada do ke nada do yang sama) dinamakan interval ...", ["Prim", "Sekon", "Terts", "Kwart"], 0, "Prim adalah interval antara nada yang sama frekuensinya (selisih 0 nada).");
addQ("sen-k6-m08", 6, "Interval Nada Sekon (1 ke 2)", "mudah", "Jarak interval antara nada do (1) ke nada re (2) yang berjarak 1 nada utuh dinamakan interval ...", ["Sekon", "Prim", "Terts", "Kuint"], 0, "Sekon adalah interval nada kedua berurutan.");
addQ("sen-k6-m09", 6, "Patung Monumen Bersejarah", "mudah", "Karya seni patung tiga dimensi yang dibangun untuk mengenang peristiwa bersejarah atau jasa pahlawan bangsa dinamakan patung ...", ["Monumen", "Dekorasi taman", "Religi pura", "Miniatur mainan"], 0, "Patung monumen mengabadikan peristiwa agung dan keteladanan pahlawan.");
addQ("sen-k6-m10", 6, "Patung Religi Sarana Ibadah", "mudah", "Karya patung tiga dimensi yang dibuat sebagai sarana peribadatan keagamaan (seperti patung Buddha di vihara atau patung Trimurti di candi) tergolong patung ...", ["Religi (keagamaan)", "Dekorasi", "Arsitektur", "Komik"], 0, "Patung religi berfungsi sakral dalam ibadah ritual keagamaan.");

addQ("sen-k6-s01", 6, "Reklame Komersial", "sedang", "Reklame yang dibuat dengan tujuan utama untuk mempromosikan barang atau jasa demi memperoleh keuntungan finansial perdagangan dinamakan reklame ...", ["Komersial", "Non-komersial (sosial)", "Rahasia", "Pribadi"], 0, "Reklame komersial bertujuan meningkatkan penjualan komoditas produk/jasa.");
addQ("sen-k6-s02", 6, "Reklame Non-Komersial (Layanan Masyarakat)", "sedang", "Poster ajakan 'Gunakan Masker Lindungi Diri dari Polusi' atau 'Ayo Ikut Imunisasi' yang dibuat oleh Kementerian Kesehatan tergolong reklame ...", ["Non-komersial (Iklan Layanan Masyarakat)", "Komersial", "Pabrik", "Jual beli"], 0, "Iklan layanan masyarakat bertujuan sosial mengedukasi publik tanpa mencari keuntungan.");
addQ("sen-k6-s03", 6, "Kemasan Produk (Embalase)", "sedang", "Desain visual pembungkus produk makanan yang memuat merk dagang, gambar menarik, dan informasi nutrisi dinamakan ...", ["Embalase (kemasan produk)", "Baliho", "Brosur", "Spanduk"], 0, "Embalase adalah seni grafis kemasan luar pelindung sekaligus promosi produk.");
addQ("sen-k6-s04", 6, "Prinsip Desain Poster yang Efektif", "sedang", "Ciri-ciri desain poster publikasi yang baik dan efektif menarik perhatian pembaca adalah ...", ["Komposisi gambar kontras menarik, tulisan singkat jelas, dan warna serasi memikat", "Huruf sangat kecil sulit dibaca", "Warna gelap gulita tanpa gambar", "Berisi teks sepanjang sepuluh halaman"], 0, "Poster efektif mengombinasikan visual eye-catching dan pesan persuasif ringkas.");
addQ("sen-k6-s05", 6, "Teknik Patung Subtraktif Memahat", "sedang", "Teknik membuat patung dengan cara mengurangi bahan sedikit demi sedikit menggunakan pahat dan palu pada bahan kayu atau batu dinamakan teknik ...", ["Subtraktif (memahat)", "Aditif (membusir menambah)", "Mengecor cairan", "Menenun benang"], 0, "Teknik subtraktif mengurangi massa bahan keras bongkahan.");
addQ("sen-k6-s06", 6, "Teknik Patung Aditif Membusir", "sedang", "Teknik membuat model patung dengan cara menambah dan menempelkan gumpalan bahan lunak (tanah liat/plastisin) pada kerangka kawat dinamakan teknik ...", ["Aditif (membusir)", "Subtraktif", "Memahat batu", "Melukis"], 0, "Teknik aditif membangun volume bentuk dengan menambahkan massa material.");
addQ("sen-k6-s07", 6, "Interval Nada Septim (1 ke 7)", "sedang", "Jarak nada dari do rendah (1) ke nada si (7) berjarak 5 1/2 nada dalam teori interval musik dinamakan interval ...", ["Septim (seventh)", "Sekt", "Kuint", "Oktaf"], 0, "Septim adalah interval nada ketujuh bertingkat.");
addQ("sen-k6-s08", 6, "Interval Nada Sekt (1 ke 6)", "sedang", "Jarak interval nada dari nada do (1) ke nada la (6) berjarak 4 1/2 nada dinamakan interval ...", ["Sekt (sixth)", "Kuint", "Kwart", "Terts"], 0, "Sekt adalah interval tangga nada keenam.");
addQ("sen-k6-s09", 6, "Ansambel Musik Melodis Ritmis Harmonis", "sedang", "Pementasan ansambel sekolah yang lengkap menggabungkan rekorder memainkan melodi, kendang memainkan ketukan, dan gitar memainkan akor pengiring. Peran gitar adalah sebagai alat musik ...", ["Harmonis", "Melodis murni", "Ritmis tanpa nada", "Peredam suara"], 0, "Alat musik harmonis memainkan paduan akor tangga nada pengiring melodi.");
addQ("sen-k6-s10", 6, "Tari Berpasangan Tari Payung", "sedang", "Tari Payung dari Minangkabau dibawakan secara berpasangan antara penari pria dan penari wanita. Properti yang dibawa penari wanita sebagai simbol perlindungan adalah ...", ["Selendang sampur (pria membawa payung)", "Piring", "Kuda kepang", "Topeng"], 0, "Penari pria memegang payung melindungi pasangannya sementara penari wanita memainkan selendang.");
addQ("sen-k6-s11", 6, "Tari Berpasangan Tari Karonsih", "sedang", "Tari Karonsih dari Jawa Tengah ditarikan secara berpasangan menceritakan tentang kisah kasih asmara antara Dewi Sekartaji dengan ...", ["Raden Panji Asmorobangun", "Prabu Hayam Wuruk", "Gajah Mada", "Ken Arok"], 0, "Tari Karonsih melukiskan kerinduan Dewi Sekartaji dan Panji Asmorobangun.");
addQ("sen-k6-s12", 6, "Tari Kelompok Massal Tari Saman", "sedang", "Tari Saman ditarikan oleh banyak penari pria dalam jumlah ganjil. Kekuatan utama keindahan Tari Saman terletak pada ...", ["Kekompakan, keselarasan ritme, dan kecepatan gerak tepukan yang serentak tanpa celah", "Kemewahan perhiasan emas", "Bunyi terompet", "Pakaian yang berbeda-beda"], 0, "Sinkronisasi kecepatan tinggi dan kekompakan kolektif adalah mahakarya Saman.");
addQ("sen-k6-s13", 6, "Tata Rias Karakter (Character Make Up)", "sedang", "Teknik merias wajah penari untuk mengubah penampilan fisik wajah menyerupai karakter tokoh tertentu (misal menjadi kakek tua berjanggut atau raksasa seram) dinamakan rias ...", ["Karakter", "Korektif cantik", "Panggung biasa", "Sehari-hari"], 0, "Rias karakter mengubah anatomi visual wajah sesuai tuntutan peran.");
addQ("sen-k6-s14", 6, "Tata Busana Tari Tradisional", "sedang", "Pakaian adat tari yang dikenakan penari di panggung harus dirancang dengan memperhatikan keindahan estetika dan tidak boleh ...", ["Mengganggu keleluasaan gerak penari saat melakukan gerakan sulit", "Sesuai tema cerita", "Menyerap keringat", "Menutupi aurat"], 0, "Kostum tari harus fungsional dan menjamin fleksibilitas gerak koreografi.");
addQ("sen-k6-s15", 6, "Pameran Seni Rupa Sekolah Dasar", "sedang", "Kegiatan memajang karya seni rupa dua dimensi dan tiga dimensi hasil karya murid di aula sekolah agar diapresiasi oleh seluruh warga sekolah dinamakan ...", ["Pameran seni rupa", "Bazar sembako", "Turnamen futsal", "Sidang kelulusan"], 0, "Pameran seni rupa memfasilitasi komunikasi estetika antara kreator murid dan audiens.");
addQ("sen-k6-s16", 6, "Buku Tamu pada Pameran Seni", "sedang", "Buku yang diletakkan di meja depan pintu masuk ruang pameran seni untuk mencatat nama pengunjung dan kesan pesan dinamakan ...", ["Buku tamu dan buku kesan pesan", "Buku absen rapor", "Buku kas keuangan", "Buku perpustakaan"], 0, "Buku tamu mencatat statistik apresiasi publik dan umpan balik pameran.");
addQ("sen-k6-s17", 6, "Katalog Pameran Seni Rupa", "sedang", "Buku panduan pameran yang memuat daftar judul karya, nama pembuat karya, ukuran, bahan, dan deskripsi konsep karya seni dinamakan ...", ["Katalog pameran", "Kuitansi", "Ijazah", "Nota belanja"], 0, "Katalog pameran memuat kurasi dokumentasi seluruh karya yang dipamerkan.");
addQ("sen-k6-s18", 6, "Karya Seni Rupa Dua Dimensi Karikatur", "sedang", "Gambar lukisan yang melebih-lebihkan atau mendistorsi ciri fisik tokoh secara lucu dan menggelikan untuk menyampaikan pesan kritik sosial dinamakan ...", ["Karikatur", "Ilustrasi komik", "Poster", "Foto paspor"], 0, "Karikatur mendistorsi proporsi anatomi tubuh secara satir untuk humor dan kritik.");
addQ("sen-k6-s19", 6, "Karya Seni Rupa Tiga Dimensi Diorama", "sedang", "Penyajian pemandangan tiga dimensi miniatur adegan sejarah masa lalu di dalam kotak kaca berlatar lukisan perspektif dinamakan ...", ["Diorama", "Lukisan kanvas", "Relief", "Sketsa"], 0, "Diorama menyajikan rekonstruksi visual 3D berskala miniatur.");
addQ("sen-k6-s20", 6, "Peran Kurator Pameran Seni", "sedang", "Seseorang yang bertugas menyeleksi karya seni yang layak dipamerkan, menata tata letak pencahayaan, dan menjelaskan makna karya kepada publik dinamakan ...", ["Kurator seni", "Kolektor barang", "Pelukis", "Satpam galeri"], 0, "Kurator memandu konsep tata pameran dan interpretasi nilai estetika karya seni.");

addQ("sen-k6-u01", 6, "Analisis Desain Embalase Produk Ramah Lingkungan", "sulit", "Tren desain embalase (kemasan produk) modern menuntut penggunaan bahan biodegradable (seperti kertas daur ulang atau serat singkong). Alasan ekologis utama pemilihan bahan ini adalah ...", ["Mengurangi timbunan sampah plastik anorganik yang mencemari lingkungan dan mudah terurai tanah", "Harganya jutaan rupiah", "Tidak bisa dicetak tulisan", "Mudah hancur terkena angin"], 0, "Eco-friendly packaging mendukung pembangunan berkelanjutan dan memangkas jejak karbon.");
addQ("sen-k6-u02", 6, "Tipografi dalam Desain Poster Efektif", "sulit", "Pemilihan gaya jenis huruf (tipografi) pada poster peringatan bahaya keselamatan harus menggunakan huruf yang berkarakter ...", ["Tegas, tebal (bold), mudah dibaca dari jarak jauh, dan tidak berbelit-belit", "Huruf sambung latin yang sangat tipis rumit", "Huruf terbalik", "Huruf warna-warni tanpa kontras"], 0, "Tipografi poster publik wajib mengutamakan keterbacaan (legibility) dan kejelasan visual (readability).");
addQ("sen-k6-u03", 6, "Analisis Layout Keseimbangan Asimetris Desain Grafis", "sulit", "Tata letak poster yang menempatkan gambar besar di sisi kiri diseimbangkan dengan teks tebal berbobot visual di sisi kanan menerapkan prinsip tata letak ...", ["Keseimbangan asimetris (asymmetrical balance)", "Keseimbangan simetri cermin", "Kekacauan layout", "Kekosongan bidang"], 0, "Asymmetrical balance menyeimbangkan bobot optik tanpa mencerminkan elemen identik.");
addQ("sen-k6-u04", 6, "Analisis Simbol Warna dalam Reklame Pangan", "sulit", "Perusahaan restoran dan produk makanan ringan sering menggunakan kombinasi warna merah dan kuning terang pada logo dan kemasannya karena secara psikologis warna tersebut ...", ["Merangsang nafsu makan, menarik perhatian spontan, dan memancarkan kehangatan ceria", "Membuat orang mengantuk", "Menimbulkan rasa takut", "Membuat makanan terasa pahit"], 0, "Warna merah dan kuning meningkatkan denyut metabolisme dan menstimulasi nafsu makan.");
addQ("sen-k6-u05", 6, "Analisis Transposisi Tangga Nada Musik", "sulit", "Jika sebuah lagu bernada dasar C mayor (C = do) dinaikkan nada dasarnya menjadi D mayor (D = do), maka susunan notasi nada lagunya mengalami proses ...", ["Transposisi (perubahan nada dasar)", "Modulasi ritme", "Sinkopasi", "Aransemen instrumen"], 0, "Transposisi memindahkan seluruh melodi lagu ke nada dasar baru dengan perbandingan interval tetap.");
addQ("sen-k6-u06", 6, "Analisis Interval Mayor vs Minor pada Nada Terts", "sulit", "Interval terts mayor (C ke E) berjarak 2 laras nada penuh dan menghasilkan nuansa musikal yang ceria, sedangkan terts minor (C ke Es) berjarak 1 1/2 laras menghasilkan nuansa ...", ["Melankolis, sayu, dan sedih", "Sangat gembira melompat", "Keras memekakkan", "Bising"], 0, "Terts kecil (minor third) 1,5 nada adalah fondasi akustik terciptanya suasana melankolis.");
addQ("sen-k6-u07", 6, "Analisis Solmisasi Tangga Nada Pentatonis Pelog", "sulit", "Tangga nada pentatonis pelog dalam gamelan Jawa menggunakan notasi angka: 1 (ji), 2 (ro), 3 (lu), 4 (pat), 5 (ma), 6 (nem), 7 (pi). Karakter musikal gending pelog cenderung ...", ["Tenang, agung, anggun, dan penuh kekhidmatan religius", "Sangat riang gembira melompat", "Cepat seperti musik disko", "Bising memekakkan"], 0, "Laras pelog menghasilkan suasana musikal yang agung, magis, dan menenangkan jiwa.");
